SELECT jsonb_build_object('database',current_database(),'posts',to_regclass('public.community_posts'),'comments',to_regclass('public.community_comments'),'profiles',(SELECT count(*) FROM profiles),'xp',(SELECT sum(xp) FROM profiles),'bucket',(SELECT to_jsonb(b) FROM storage.buckets b WHERE id='community-images'),'reports_policies',(SELECT jsonb_agg(to_jsonb(p)) FROM pg_policies p WHERE tablename='content_reports'),'linked_history',(SELECT jsonb_agg(version) FROM (SELECT version FROM supabase_migrations.schema_migrations ORDER BY version DESC LIMIT 4) m)) AS audit;
